//! Contract checks for exact time helpers, SMPTE displays and hostile editor input.
//! Assertions are against fixed documented values, not snapshots generated by the implementation.

use effectcraft_time::{FrameRate, ParseError, Tick, TimeDisplay, format_time, format_timecode_ae, parse_timecode};

#[test]
fn tick_helper_operations_saturate_and_preserve_fractional_seconds() {
    let t = Tick::from_seconds_f64(1.25);
    assert_eq!(t.seconds(), 1.25);
    assert_eq!(Tick(-5).abs(), Tick(5));
    assert_eq!(Tick(i64::MIN).abs(), Tick(i64::MAX));
    assert_eq!(Tick(5).clamp(Tick(0), Tick(3)), Tick(3));
    assert_eq!(Tick(-5).clamp(Tick(0), Tick(3)), Tick(0));
    assert_eq!(Tick(2).clamp(Tick(0), Tick(3)), Tick(2));

    let mut near_max = Tick(i64::MAX - 1);
    near_max += Tick(100);
    assert_eq!(near_max, Tick(i64::MAX));
    near_max -= Tick(1);
    assert_eq!(near_max, Tick(i64::MAX - 1));
    let mut near_min = Tick(i64::MIN + 1);
    near_min -= Tick(100);
    assert_eq!(near_min, Tick(i64::MIN));
    near_min += Tick(1);
    assert_eq!(near_min, Tick(i64::MIN + 1));
}

#[test]
fn default_frame_rate_and_display_labels_match_public_contract() {
    assert_eq!(FrameRate::default(), FrameRate::FPS_23_976);
    assert_eq!(FrameRate::FPS_24.label(), "24");
    assert_eq!(FrameRate::FPS_24.to_string(), "24 fps");
    assert_eq!(TimeDisplay::ALL.len(), 6);
    assert_eq!(TimeDisplay::Timecode.label(), "Timecode");
    assert_eq!(TimeDisplay::Frames.label(), "Frames");
    assert_eq!(TimeDisplay::Feet16.label(), "Feet + Frames 16mm");
    assert_eq!(TimeDisplay::Feet35.label(), "Feet + Frames 35mm");
    assert_eq!(TimeDisplay::AudioSamples.label(), "Audio Samples");
    assert_eq!(TimeDisplay::Seconds.label(), "Seconds");
    assert_eq!(format_time(Tick::from_seconds_f64(1.25), FrameRate::FPS_24, false, TimeDisplay::Seconds, 48_000), "1.250");
}

#[test]
fn editing_timecode_displays_unpadded_hours_and_correct_frame_width() {
    assert_eq!(format_timecode_ae(61, FrameRate::FPS_24, false), "0:00:02:13");
    assert_eq!(format_timecode_ae(-1, FrameRate::FPS_24, false), "-0:00:00:01");
    assert_eq!(format_timecode_ae(1800, FrameRate::FPS_29_97, true), "0;01;00;02");
    assert_eq!(format_timecode_ae(7200, FrameRate::FPS_119_88, true), "0;01;00;008");
}

#[test]
fn malformed_timecodes_report_actionable_displayable_errors() {
    let rate = FrameRate::FPS_24;
    assert_eq!(parse_timecode("", rate, false, 0).unwrap_err(), ParseError("empty timecode".into()));
    assert_eq!(parse_timecode("  ", rate, false, 0).unwrap_err().to_string(), "empty timecode");
    assert_eq!(parse_timecode("00:00:00:00:00", rate, false, 0).unwrap_err().to_string(), "too many timecode fields");
}
